export function gamesForTeam(teamName: string): Game[] {
  return GAMES.filter((g) => g.home === teamName || g.away === teamName).sort(
    (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()
  );
}

export const WEEKS = Array.from({ length: 16 }, (_, i) => ({
  key: `week${i + 1}`,
  label: `Week ${i + 1}`,
}));
